pub mod benchmark_service_server {
    pub trait BenchmarkService: Send + Sync + 'static {
        type ClientStreamingStream: futures::Future<Output = Result<tonic::Response<super::SimpleResponse>, tonic::Status>> + Send;
        type ServerStreamingStream: futures::Stream<Item = Result<super::SimpleResponse, tonic::Status>> + Send;
        type BidirectionalStreamingStream: futures::Stream<Item = Result<super::SimpleResponse, tonic::Status>> + Send;
        type FloodTestStream: futures::Future<Output = Result<tonic::Response<super::BenchmarkResponse>, tonic::Status>> + Send;
        type StreamTestStream: futures::Stream<Item = Result<super::BenchmarkResponse, tonic::Status>> + Send;

        fn unary_call(&self, request: tonic::Request<super::SimpleRequest>) -> Self::ClientStreamingStream;
        fn client_streaming(&self, request: tonic::Request<tonic::Streaming<super::SimpleRequest>>) -> Self::ClientStreamingStream;
        fn server_streaming(&self, request: tonic::Request<super::SimpleRequest>) -> Self::ServerStreamingStream;
        fn bidirectional_streaming(&self, request: tonic::Request<tonic::Streaming<super::SimpleRequest>>) -> Self::BidirectionalStreamingStream;
        fn latency_test(&self, request: tonic::Request<super::BenchmarkRequest>) -> Self::FloodTestStream;
        fn flood_test(&self, request: tonic::Request<tonic::Streaming<super::BenchmarkRequest>>) -> Self::FloodTestStream;
        fn stream_test(&self, request: tonic::Request<tonic::Streaming<super::BenchmarkRequest>>) -> Self::StreamTestStream;
    }

    pub struct BenchmarkServiceServer<T> {
        service: T,
    }

    impl<T> BenchmarkServiceServer<T> {
        pub fn new(service: T) -> Self {
            Self { service }
        }
    }
}